lay: flex;\n  align-items: center;\n  justify-content: space-between;\n  font-size: 11px;\n  color: var(--b-muted, #9a8f98);\n}\n\n.coin-row {\n  display: grid;\n  grid-template-columns: 70px 110px 1fr 30px;\n  gap: 6px;\n  align-items: center;\n}\n\n.effect-preview {\n  display: flex;\n  flex-direction: column;\n  gap: 3px;\n  padding: 6px 8px;\n  border: 1px dashed var(--b-border, #3b303b);\n  border-radius: 5px;\n  background: rgba(217, 164, 65, 0.06);\n  font-size: 11px;\n  line-height: 1.6;\n}\n\n.preview-line {\n  display: flex;\n  gap: 6px;\n  align-items: baseline;\n}\n\n.preview-label {\n  padding: 0 5px;\n  border-radius: 3px;\n  background: rgba(217, 164, 65, 0.18);\n  color: var(--b-accent-2, #d9a441);\n  font-size: 10px;\n}\n\n.preview-warn,\n.hint {\n  color: #e88a7c;\n  font-size: 11px;\n}\n\n@media (max-width: 720px) {\n  .lib-body {\n    grid-template-columns: 1fr;\n  }\n\n  .field-grid {\n    grid-template-columns: 1fr;\n  }\n\n  .coin-row {\n    grid-template-columns: 60px 1fr 30px;\n  }\n\n  .coin-effect {\n    grid-column: 1 / -1;\n  }\n}\n</style>\n"],"sourceRoot":""}]);
