/* ------------------------------------------------------------------ *
 * 存储: 内置默认库 + 全局变量覆盖层
 * ------------------------------------------------------------------ */
const 存储键 = '技能库';
const 全局变量选项 = { type: 'global' };
function 读取存储() {
    try {
        const 全局 = getVariables(全局变量选项) ?? {};
        const 原始 = 全局[存储键];
        return {
            覆盖: 原始 && typeof 原始.覆盖 === 'object' && 原始.覆盖 ? 原始.覆盖 : {},
            删除: 原始 && Array.isArray(原始.删除) ? 原始.删除 : [],
        };
    }
    catch (错误) {
        console.warn('[技能库] 读取全局变量失败, 使用空覆盖层:', 错误);
        return { 覆盖: {}, 删除: [] };
    }
}
let 存储 = 读取存储();
function 保存() {
    try {
        const 全局 = getVariables(全局变量选项) ?? {};
        replaceVariables({ ...全局, [存储键]: klona(存储) }, 全局变量选项);
    }
    catch (错误) {
        console.error('[技能库] 写入全局变量失败:', 错误);
    }
}
/** 默认库 + 全局覆盖 (删除项被剔除) */
function 合并() {
    const 结果 = {};
    for (const [名, 定义] of Object.entries(默认技能库)) {
        if (!存储.删除.includes(名))
            结果[名] = { ...定义, 名称: 名 };
    }
    for (const [名, 定义] of Object.entries(存储.覆盖)) {
        if (!存储.删除.includes(名))
            结果[名] = { ...定义, 名称: 名 };
    }
    return 结果;
}
function 是内置(名) {
    return Object.prototype.hasOwnProperty.call(默认技能库, 名);
}
/* ------------------------------------------------------------------ *
 * 共享 API
 * ------------------------------------------------------------------ */
export const 技能库API = {
    查: 名 => {
        const 定义 = 合并()[名];
        return 定义 ? klona(定义) : undefined;
    },
    全部: () => klona(合并()),
    内存列表: () => Object.values(合并())
        .map(定义 => klona(定义))
        .sort((甲, 乙) => 甲.名称.localeCompare(乙.名称, 'zh-Hans-CN')),
    增: (名, 定义) => {
        if (!名)
            return;
        存储.覆盖[名] = { ...klona(定义), 名称: 名 };
        存储.删除 = 存储.删除.filter(项 => 项 !== 名);
        保存();
    },
    改: (名, 定义) => {
        if (!名)
            return;
        存储.覆盖[名] = { ...klona(定义), 名称: 名 };
        存储.删除 = 存储.删除.filter(项 => 项 !== 名);
        保存();
    },
    删: 名 => {
        delete 存储.覆盖[名];
        if (是内置(名) && !存储.删除.includes(名))
            存储.删除.push(名);
        保存();
    },
    导入: json => {
        const 数据 = 解析导入(json);
        存储.覆盖 = 数据;
        存储.删除 = Object.keys(默认技能库).filter(名 => !(名 in 数据));
        保存();
    },
    导出: 名 => {
        if (名) {
            const 定义 = 合并()[名];
            return 定义 ? JSON.stringify(定义, null, 2) : '';
        }
        return JSON.stringify(合并(), null, 2);
    },
    重置: () => {
        存储 = { 覆盖: {}, 删除: [] };
        保存();
    },
};
function 解析导入(json) {
    const 解析 = JSON.parse(json);
    if (!解析 || typeof 解析 !== 'object' || Array.isArray(解析)) {
        throw Error('技能库 JSON 应为「技能名 -> 技能定义」的对象');
    }
    const 结果 = {};
    for (const [名, 定义] of Object.entries(解析)) {
        if (!定义 || typeof 定义 !== 'object' || Array.isArray(定义)) {
            throw Error(`技能「${名}」的定义不是对象`);
        }
        const 对象 = 定义;
        结果[名] = {
            ...对象,
            名称: 名,
            类别: 对象.类别 ?? '战斗',
        };
    }
    return 结果;
}
